import {ShieldLockIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import type {CopilotForBusinessGeneralPolicy} from '../types'
import PolicyActionMenu from './PolicyActionMenu'

/******************************************************
 * This is the same as GeneralPolicy.tsx,             *
 * but with useOptions provided as props              *
 * so that the state can be shared with McpRegistry.  *
 ******************************************************/

export default function McpPolicy({
  policy,
  onSelect,
  options,
  selected,
  loading,
  enterpriseAllowlistEnabled = false,
}: {
  policy: CopilotForBusinessGeneralPolicy
  onSelect: (item: ActionMenuButtonOption) => Promise<void>
  options: ActionMenuButtonOption[]
  selected: ActionMenuButtonOption | undefined
  loading: boolean
  enterpriseAllowlistEnabled?: boolean
}) {
  const disabled = !policy.configurable
  if (!policy.visible) return null

  if (enterpriseAllowlistEnabled) {
    return (
      <>
        <div data-testid={`cfb-policies-${policy.manages}-feature`} style={{maxWidth: 750}}>
          <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
          {policy.description}
          <br />
          {policy.helpurl && policy.helptext && (
            <Link href={policy.helpurl} inline>
              {policy.helptext}
            </Link>
          )}
        </div>
        <span data-testid="cfb-policies-mcp-feature-locked">
          <ShieldLockIcon /> Lorem Ipsum
        </span>
      </>
    )
  }

  return (
    <>
      <div data-testid={`cfb-policies-${policy.manages}-feature`} style={{maxWidth: 750}}>
        <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
        {policy.description}
        <br />
        {policy.helpurl && policy.helptext && (
          <Link href={policy.helpurl} inline>
            {policy.helptext}
          </Link>
        )}
      </div>
      <PolicyActionMenu
        options={options}
        onSelect={onSelect}
        disabled={disabled}
        selected={selected}
        loading={loading}
        actionMenuTestId={`cfb-policies-mcp-control`}
        disabledTestId={`cfb-policies-mcp-feature-locked`}
      />
    </>
  )
}
