import type React from 'react'
import {useMemo} from 'react'

import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {Box} from '@primer/styled-react'
import {Bold} from './Ui'
import type {SeatType} from '../../types'

export const SeatHovercardLink = (
  props: React.PropsWithChildren<{
    assignable_type: SeatType
    owner: string
    login: string
    className?: string
    testId?: string
    color?: string
  }>,
) => {
  const {login, assignable_type, owner, className, testId, children, color} = props

  const href = useMemo(() => {
    switch (assignable_type) {
      case 'User':
        return `/orgs/${owner}/people/${login}`
      case 'Team':
        return `/orgs/${owner}/teams/${login}`
      case 'OrganizationInvitation':
        return `/${login}`
      case 'Organization':
        return `/orgs/${owner}/people/${login}`
      case 'EnterpriseTeam':
        return `/enterprises/${owner}/external_group_members/${login}`
      default:
        return ''
    }
  }, [assignable_type, owner, login])

  // Use appropriate hovercard type and params based on assignable_type
  const isTeam = assignable_type === 'Team'
  const isUser =
    assignable_type === 'User' || assignable_type === 'OrganizationInvitation' || assignable_type === 'Organization'

  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const hovercardAttrs = isTeam
    ? getHovercardAttributesForType('team', {owner, team: isTeam ? login : undefined, zIndexOverride: 1000})
    : getHovercardAttributesForType('user', {login: isUser ? login : undefined, zIndexOverride: 1000})

  return (
    <Box
      as="a"
      sx={{color: color || 'fg.default', whiteSpace: 'nowrap'}}
      className={className}
      {...hovercardAttrs}
      data-testid={testId}
      href={href}
      aria-label={login}
    >
      <Bold>{children}</Bold>
    </Box>
  )
}
