const FocusModeSections = {
  'code-review': 'Copilot code review',
  'copilot-insights': 'Copilot Insights',
  'coding-agent': 'Copilot coding agent',
  'mcp-servers': 'MCP servers in Copilot',
  'agent-mode': 'Copilot agent mode',
  cli: 'Copilot CLI',
} as const

type FocusModeSectionKey = keyof typeof FocusModeSections

/**
 * "Focus mode" allows navigating to this page with a query param e.g. `?feature=code-review` which only renders the requested relevant sections.
 *
 * When a valid FocusMode key is provided, the UI hides all other sections that aren't relevant to that feature and only shows the requested section (subject to its normal rendering condition).
 *
 * When either an invalid FocusMode key is provided or no FocusMode key is provided, then all sections display normally according to their own conditions
 */
function getFocusMode(focusModeSectionTitle: typeof FocusModeSections) {
  const QUERY_PARAM_FOCUSMODE = 'feature'

  const isFocusModeFeatureFlagEnabled = isFeatureEnabled('copilot_org_policy_page_focus_mode')

  const urlParams = new URLSearchParams(ssrSafeLocation.search)
  const focusModeParam = urlParams.get(QUERY_PARAM_FOCUSMODE) as null | FocusModeSectionKey
  const activeFocusModeKey =
    isFocusModeFeatureFlagEnabled && focusModeParam && focusModeParam in focusModeSectionTitle ? focusModeParam : false

  function getSectionTitle() {
    if (activeFocusModeKey) {
      return focusModeSectionTitle[activeFocusModeKey]
    }
    return 'Features'
  }

  function shouldShowSection(
    condition: null | undefined | boolean,
    focusModeSectionKey?: FocusModeSectionKey,
  ): condition is true {
    if (activeFocusModeKey) {
      // If we're in focus mode, then only show the appropriate section
      return !!(activeFocusModeKey === focusModeSectionKey && condition)
    }

    // Otherwise show the sections normally
    return !!condition
  }

  function getAllFeaturesUrl() {
    const url = new URL(ssrSafeLocation.href, ssrSafeLocation.origin)
    const params = new URLSearchParams(ssrSafeLocation.search)
    params.delete(QUERY_PARAM_FOCUSMODE)
    if (params.size === 0) {
      return url.pathname
    }
    return `${url.pathname}?${params.toString()}`
  }

  const AllFeaturesLink = () => (
    <Link inline href={getAllFeaturesUrl()}>
      View all features
    </Link>
  )

  return {activeFocusModeKey, shouldShowSection, getSectionTitle, AllFeaturesLink}
}

export function PoliciesPage({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const {shouldShowSection, activeFocusModeKey, getSectionTitle, AllFeaturesLink} = getFocusMode(FocusModeSections)

  // This function wraps shouldShowSection to limit visible policy sections when Copilot is disabled for
  // the organization. In this mode, org admins should still be able to manage direct org billing policies
  // for Code Review, Coding Agent, and CLI. https://github.com/github/Copilot-Controls/issues/9848
  const policiesShownWhenCopilotDisabled = ['code-review', 'coding-agent', 'cli'] as FocusModeSectionKey[]
  function shouldShowPolicySection(
    condition: null | undefined | boolean,
    focusModeSectionKey?: FocusModeSectionKey,
  ): boolean {
    if (payload.show_policies_when_copilot_disabled) {
      if (policiesShownWhenCopilotDisabled.includes(focusModeSectionKey as FocusModeSectionKey)) {
        return shouldShowSection(condition, focusModeSectionKey)
      }
      return false
    } else {
      return shouldShowSection(condition, focusModeSectionKey)
    }
  }

  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const copilotExtensionAccessFeatureFlag = useFeatureFlag('copilot_extension_access')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const hideCopilotExtensionPolicyFeatureFlag = useFeatureFlag('hide_copilot_extensions_policy')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const mcpEnterpriseAllowlistUIFeatureFlag = useFeatureFlag('copilot_mcp_registry_enterprise_allowlist_ui')
  const showCopilotBing = shouldShowPolicySection(payload.bing_github_chat.visible)
  const showModelNativeSearch = shouldShowPolicySection(payload.model_native_search?.visible)
  const showCopilotForDotcom = shouldShowPolicySection(payload.copilot_for_dotcom.visible)
  const showCopilotExtensionsPolicySection = shouldShowPolicySection(
    copilotExtensionAccessFeatureFlag && !hideCopilotExtensionPolicyFeatureFlag,
  )
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCopilotTelemetryPolicy = shouldShowPolicySection(useFeatureFlag('copilot_private_telemetry_access'))
  const showCopilotDesktopPolicy = shouldShowPolicySection(payload.desktop.visible)
  const showEditorPreviewFeatures = shouldShowPolicySection(payload.editor_preview_features.visible)
  const showAgentMode = shouldShowPolicySection(payload.agent_mode.visible, 'agent-mode')
  const showAgentModeAutoApprove = shouldShowPolicySection(payload.agent_mode_auto_approve.visible)
  const showInsightsPolicy = shouldShowPolicySection(payload.insights.visible, 'copilot-insights')
  const showMcpPolicy = shouldShowPolicySection(payload.mcp.visible, 'mcp-servers')
  const showMcpRegistry = shouldShowPolicySection(payload.mcp_registry.visible)
  const showMcpRegistryAccess = shouldShowPolicySection(payload.mcp_registry_access.visible)
  const showMcpEnterpriseAllowlistUI = showMcpPolicy && mcpEnterpriseAllowlistUIFeatureFlag
  const showOveragesPolicy = shouldShowPolicySection(payload.overages.visible)
  const showCodeReviewPolicy = shouldShowPolicySection(payload.code_review.visible, 'code-review')
  const showSparkPolicy = shouldShowPolicySection(payload.spark.visible)
  const showSweAgentPolicy = shouldShowPolicySection(payload.swe_agent.visible, 'coding-agent')
  const showCli = shouldShowPolicySection(payload.cli.visible, 'cli')
  const showGeneratedCommitMessagePolicy = shouldShowPolicySection(payload.generated_commit_message?.visible)
  const showMemoryPolicy = shouldShowPolicySection(payload.memory?.visible)

  const memberRequestFeatureName = payload.member_feature_request?.feature_name
  const isMemberFeatureRequestCompleted = payload.member_feature_request?.request_completed && memberRequestFeatureName
  const {enterprise_name, enterprise_slug, copilot_plan: plan, docsUrls, org_name} = payload

  const mcp = useMcpPolicyState(payload)

  const hasBannerPortal = (showMcpRegistry || showMcpRegistryAccess) && !mcpEnterpriseAllowlistUIFeatureFlag
  const [isMemberRequestBannerShown, setMemberRequestBannerShown] = useState(isMemberFeatureRequestCompleted)
  return (
    <>
      {hasBannerPortal && mcp.bannerMessage?.message && (
        <BannerPortal
          message={mcp.bannerMessage.message}
          variant={mcp.bannerMessage.variant}
          onDismiss={mcp.dismissBanner}
        />
      )}
      {isMemberRequestBannerShown && (
        <Banner
          className="tmp-mb-3"
          variant="success"
          title="Member request enabled"
          hideTitle
          description={`${memberRequestFeatureName} is now enabled for everyone with a Copilot license in your organization.`}
          onDismiss={() => setMemberRequestBannerShown(false)}
          data-testid="member-request-banner"
        />
      )}
      <PageHeading name="GitHub Copilot" />
      <div className={clsx(styles.topBox, 'tmp-mb-3')}>
        <span className={clsx(styles.muted, 'tmp-mb-3')}>
          You can manage policies and grant access to Copilot features for all members with access.
          <br />
          Note that users from other organizations may gain access if permitted by their administrators.
        </span>
        {enterprise_name && enterprise_slug && (
          <span className={clsx(styles.muted, 'mr-2', 'tmp-mb-3')} data-testid="cfb-managed-organization-enterprise">
            <ShieldLockIcon /> Managed by{' '}
            <Link inline href={`/enterprises/${enterprise_slug}`}>
              {enterprise_name}
            </Link>
          </span>
        )}
      </div>
      {/*============== START OF BILLING POLICIES SECTION ==============*/}
      {/*
        today, overages is the only billing policy
        if more billing policies are added in the future, the conditions need to be modified/removed
      */}
      {showOveragesPolicy && (
        <Box
          data-hpc
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--stack-gap-normal)',
            marginBottom: 3,
          }}
        >
          <SectionHeading name="Billing" />
          <BoxSection>
            <OveragesPolicy
              enterprise_name={enterprise_name}
              org_name={org_name}
              payload={payload}
              enterprise_slug={enterprise_slug}
            />
          </BoxSection>
        </Box>
      )}
      {/*============== END OF BILLING POLICIES SECTION ==============*/}

      {/*============== START OF FEATURES POLICIES SECTION ==============*/}
      <Box
        data-hpc
        sx={{
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--stack-gap-normal)',
          marginBottom: 3,
        }}
      >
        <SectionHeading name={getSectionTitle()} />
        {activeFocusModeKey && <AllFeaturesLink />}
        <BoxSection>
          {showCopilotForDotcom && <CopilotForDotcomPolicy payload={payload} />}
          {showSparkPolicy && <SparkPolicy payload={payload} />}
          {shouldShowPolicySection(true) && <GeneralPolicy payload={payload} policy={payload.editor_chat} />}
          {showEditorPreviewFeatures && <GeneralPolicy payload={payload} policy={payload.editor_preview_features} />}
          {showAgentMode && <GeneralPolicy payload={payload} policy={payload.agent_mode} />}
          {showAgentModeAutoApprove && <GeneralPolicy payload={payload} policy={payload.agent_mode_auto_approve} />}
          {shouldShowPolicySection(true) && <GeneralPolicy payload={payload} policy={payload.mobile_chat} />}
          {showCli && <CopilotCliPolicy payload={payload} />}
          {showCopilotDesktopPolicy && <GeneralPolicy payload={payload} policy={payload.desktop} />}
          {showCopilotExtensionsPolicySection && <CopilotExtensionsPolicy payload={payload} />}
          {showCopilotBing && <GeneralPolicy payload={payload} policy={payload.bing_github_chat} />}
          {showModelNativeSearch && payload.model_native_search && (
            <GeneralPolicy payload={payload} policy={payload.model_native_search} />
          )}
          {shouldShowPolicySection(true) && (
            <GeneralPolicy payload={payload} policy={payload.copilot_usage_metrics_policy} />
          )}
          {showInsightsPolicy && <CopilotInsightsPolicy payload={payload} />}
          {showCodeReviewPolicy && <CopilotCodeReviewPolicy payload={payload} />}
          {showSweAgentPolicy && <CopilotCodingAgentPolicy payload={payload} />}
          {showMemoryPolicy && payload.memory && <GeneralPolicy payload={payload} policy={payload.memory} />}

          {/*==== MCP Policies section ====*/}

          {showMcpPolicy && (
            <McpPolicy
              policy={payload.mcp}
              onSelect={mcp.mcpOptions.onSelect}
              options={mcp.mcpOptions.options}
              selected={mcp.mcpOptions.selected}
              loading={mcp.mcpOptions.loading}
              enterpriseAllowlistEnabled={mcpEnterpriseAllowlistUIFeatureFlag}
            />
          )}
          {showMcpRegistry && !mcpEnterpriseAllowlistUIFeatureFlag && (
            <McpRegistry
              mcpRegistry={payload.mcp_registry}
              value={mcp.registryUrl}
              onChange={mcp.setRegistryUrl}
              loading={mcp.loading}
              onSubmit={e => {
                e.preventDefault()
                mcp.submitRegistryUrl()
              }}
              onDelete={() => {
                mcp.setRegistryUrl('')
                mcp.submitRegistryUrl('')
              }}
              inputDisabled={mcp.mcpPolicyDisabled || mcp.loading || !payload.mcp_registry.configurable}
            />
          )}
          {showMcpRegistryAccess && !mcpEnterpriseAllowlistUIFeatureFlag && (
            <McpRegistryAccess
              options={mcp.mcpRegistryAccessOptions.options}
              selected={mcp.registryAccess}
              onSelect={mcp.submitRegistryAccess}
              loading={mcp.loading}
              policy={payload.mcp_registry_access}
              inputDisabled={
                !payload.mcp_registry_access.configurable ||
                mcp.mcpPolicyDisabled ||
                mcp.loading ||
                !mcp.registryUrl ||
                !isValidUrl(mcp.registryUrl)
              }
            />
          )}
          {showMcpEnterpriseAllowlistUI && <McpRegistryPolicy />}
          {showMcpEnterpriseAllowlistUI && <McpAssignedAllowlist />}
          {showMcpEnterpriseAllowlistUI && <McpBlockLocalServers />}

          {showGeneratedCommitMessagePolicy && (
            <GeneralPolicy payload={payload} policy={payload.generated_commit_message!} />
          )}

          {shouldShowPolicySection(payload.spaces?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.spaces!} />
          )}
          {shouldShowPolicySection(payload.spaces_individual_access?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.spaces_individual_access!} className="tmp-ml-3" />
          )}
          {shouldShowPolicySection(payload.spaces_individual_sharing?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.spaces_individual_sharing!} className="tmp-ml-3" />
          )}

          {shouldShowPolicySection(payload.restrict_to_azure?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.restrict_to_azure!} />
          )}
          {shouldShowPolicySection(payload.restrict_to_fedramp?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.restrict_to_fedramp!} />
          )}
          {shouldShowPolicySection(payload.restrict_to_data_residency?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.restrict_to_data_residency!} />
          )}
          {shouldShowPolicySection(payload.client_byok?.visible) && (
            <GeneralPolicy payload={payload} policy={payload.client_byok!} />
          )}
        </BoxSection>
      </Box>
      {/*============== END OF FEATURES POLICIES SECTION ==============*/}

      {/*============== START OF PRIVACY POLICIES SECTION ==============*/}
      {shouldShowPolicySection(true) && (
        <Box
          data-hpc
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--stack-gap-normal)',
            marginBottom: 3,
          }}
        >
          <SectionHeading name="Duplicate Detection Filter" />
          <BoxSection>
            <GeneralPolicy payload={payload} policy={payload.snippy} />
            {showCopilotTelemetryPolicy && <CopilotTelemetryPolicy payload={payload} />}
          </BoxSection>
        </Box>
      )}
      {/*============== END OF PRIVACY POLICIES SECTION ==============*/}

      {shouldShowPolicySection(true) && (
        <Box
          data-hpc
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--stack-gap-normal)',
            marginBottom: 3,
          }}
        >
          <Text as="p" sx={{color: 'fg.muted'}} data-testid="cb-policies-footnotes">
            {' '}
            {plan !== 'enterprise' && <FeaturesForDataRetention copilotForDotcomVisible={showCopilotForDotcom} />}
            If preview features are enabled, you agree to{' '}
            <Link
              href="https://docs.github.com/site-policy/github-terms/github-copilot-pre-release-license-terms"
              inline
            >
              pre-release terms
            </Link>
            . For more information about the data your organization receives regarding your use of GitHub Copilot,
            please review{' '}
            <Link href={docsUrls.generalPrivacyStatement} inline>
              GitHub&apos;s Privacy Statement
            </Link>
            .
          </Text>
        </Box>
      )}
    </>
  )
}

function CopilotForDotcomPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isCopilotChatGA = useFeatureFlag('copilot_chat_dotcom_ga')
  const showCodeReviewPolicy = payload.code_review.visible
  const data = payload.copilot_for_dotcom
  const {copilot_plan: plan} = payload
  const isEnterprisePlan = plan === 'enterprise'

  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: data.options,
    controls: data.manages,
  })

  const disabled = !data.configurable

  // Determines what list separate to use depending on which features can be enabled by the organization
  const copilotCodeReviewListSeparator = isEnterprisePlan ? ', ' : ', and'

  return (
    <Box sx={{display: 'flex', flexDirection: 'column', width: '100%'}}>
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: selected?.value === 'enabled' ? 'start' : 'center',
        }}
      >
        <div data-testid="cfb-policies-dotcom-bundle-feature">
          <PreviewFeatureHeading title="Copilot in GitHub.com" beta={!isEnterprisePlan && !isCopilotChatGA} />
          {showCodeReviewPolicy ? (
            <div>
              If enabled, members of this organization can use{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-chat-in-github/about-github-copilot-chat"
                inline
              >
                Copilot Chat in GitHub.com
              </Link>
              .
            </div>
          ) : (
            <div>
              If enabled, members of this organization can use{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-chat-in-github/about-github-copilot-chat"
                inline
              >
                Copilot Chat in GitHub.com
              </Link>
              ,{' '}
              <Link
                href="https://docs.github.com/copilot/github-copilot-enterprise/copilot-pull-request-summaries/about-copilot-pull-request-summaries"
                inline
              >
                Copilot for pull requests
              </Link>
              {copilotCodeReviewListSeparator}{' '}
              <Link
                href="https://docs.github.com/en/enterprise-cloud@latest/copilot/using-github-copilot/code-review/using-copilot-code-review"
                inline
              >
                Copilot code review
              </Link>
              .
            </div>
          )}
          {selected?.value === 'enabled' && <UserFeedbackPolicy payload={payload} />}
          {selected?.value === 'enabled' && <CopilotForDotcomBetaFeaturesPolicy payload={payload} />}
        </div>
        <PolicyActionMenu
          options={options}
          onSelect={onSelect}
          selected={selected}
          loading={loading}
          actionMenuTestId="cfb-policies-dotcom-bundle-feature-button"
          disabledTestId="cfb-policies-dotcom-feature-locked"
          disabled={disabled}
        />
      </Box>
    </Box>
  )
}

function CopilotCodingAgentPolicy({payload}: {payload: CopilotForBusinessPoliciesPayload}) {
  const policy = payload.swe_agent

  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: policy.options,
    controls: policy.manages,
  })

  const disabled = !policy.configurable

  const hasMemberRequests = !!payload.swe_agent_member_requests

  const [showMemberRequests, setShowMemberRequests] = useState(hasMemberRequests)
  const handleSelect = useCallback(
    (item: ActionMenuButtonOption) => {
      const prevValue = selected?.value
      onSelect(item)
      if (hasMemberRequests && item.value !== prevValue) {
        setShowMemberRequests(false)
      }
    },
    [onSelect, selected?.value, hasMemberRequests],
  )

  if (!policy.visible) {
    return null
  }

  return (
    <Box sx={{display: 'flex', flexDirection: 'column', width: '100%'}}>
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'start',
        }}
      >
        <div data-testid="cfb-policies-swe_agent-feature" style={{maxWidth: 750}}>
          <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
          {policy.description}
          <br />
          {policy.helpurl && policy.helptext && (
            <Link href={policy.helpurl} inline>
              {policy.helptext}
            </Link>
          )}
          {hasMemberRequests && showMemberRequests && payload.swe_agent_member_requests && (
            <div style={{marginTop: '16px'}}>
              <MemberRequestsComponent memberRequests={payload.swe_agent_member_requests} entityType="member" />
            </div>
          )}
          {selected?.value === 'enabled' && <CcaDirectOrgBillingPolicy payload={payload} />}
        </div>
        <PolicyActionMenu
          options={options}
          onSelect={handleSelect}
          selected={selected}
          loading={loading}
          actionMenuTestId="cfb-policies-swe_agent-control"
          disabledTestId="cfb-policies-swe_agent-feature-locked"
          disabled={disabled}
        />
      </Box>
    </Box>
  )
}

