import {Button} from '@primer/react'
import {Box} from '@primer/styled-react'
import {CheckIcon, FileIcon} from '@primer/octicons-react'
import {ActionsBar} from './ActionsBar'
import {FilterableSearch} from './FilterableSearch'
import {useSeatManagementContext} from '../hooks/use-seat-management-context'
import {useCreateCSV} from '../../hooks/use-create-csv'
import {standaloneActivityEndpoint} from '../helpers/api-endpoints'
import {useState} from 'react'
import {createPortal} from 'react-dom'
import {CopilotFlash} from '../../components/CopilotFlash'

type Props = {
  onSearch: (value: string) => void
  onAddTeams: () => void
}
type ReportExportStatus = 'idle' | 'legacy' | 'activity'

const CSVSuccessMessage = ({onClose, isAsync = false}: {onClose: () => void; isAsync: boolean}) => {
  const container = document.getElementById('js-flash-container')
  if (!container) return null
  const message = isAsync
    ? 'Your activity report is being generated. You will receive an email when it is ready to download.'
    : 'The CSV report is being generated and successfully exported.'

  return createPortal(
    <CopilotFlash full variant="success" onClose={onClose} sx={{display: 'flex', justifyContent: 'space-between'}}>
      <div>
        <CheckIcon />
        {message}
      </div>
    </CopilotFlash>,
    container,
  )
}

export function StandaloneActionsBar({onSearch, onAddTeams}: Props) {
  const {payload} = useSeatManagementContext()
  const [reportExportStatus, setReportExportStatus] = useState<ReportExportStatus>('idle')
  const {loading: activityCsvLoading, makeCSVRequest: makeActivityCSVRequest} = useCreateCSV({
    slug: payload.business.slug,
    endpoint: standaloneActivityEndpoint,
    async: true,
    onSuccess: () => setReportExportStatus('activity'),
  })
  const isFlashVisible = reportExportStatus !== 'idle'
  const isAsyncCSVMessage = reportExportStatus === 'activity'

  return (
    <section aria-label="Management actions">
      {isFlashVisible && (
        <CSVSuccessMessage isAsync={isAsyncCSVMessage} onClose={() => setReportExportStatus('idle')} />
      )}
      <ActionsBar>
        <ActionsBar.LeftAction>
          <Box sx={{width: '25%'}}>
            <Box sx={{display: 'flex'}}>
              <FilterableSearch placeholder="Filter enterprise teams" search={onSearch} />
            </Box>
          </Box>
        </ActionsBar.LeftAction>
        <ActionsBar.RightAction>
          <Box sx={{display: 'flex', alignItems: 'center', gap: '.5rem'}}>
            <Button
              leadingVisual={FileIcon}
              onClick={makeActivityCSVRequest}
              loading={activityCsvLoading}
              disabled={activityCsvLoading}
            >
              Get activity report
            </Button>
            <Button variant="primary" onClick={onAddTeams}>
              Add teams
            </Button>
          </Box>
        </ActionsBar.RightAction>
      </ActionsBar>
    </section>
  )
}
