import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {PickerRepository} from '@github-ui/repos-picker'
import {modes} from '@github-ui/repos-picker/modes'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Banner, Label, Link, Stack} from '@primer/react'
import {useState} from 'react'
import type {CopilotSweAgentPayload, SelectionMode} from '../types'
import {PageHeading, SectionHeading} from '../traditional/components/Ui'
import styles from './Policies.module.css'
import {ControlGroup} from '@github-ui/control-group'
import {ShieldLockIcon} from '@primer/octicons-react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {copilotForBusinessSweAgentRoute} from './swe-agent-route'
import {CopilotSweAgentThirdPartyAgentPicker} from '@github-ui/copilot-swe-agent-third-party-agent-picker'

export function SweAgentPageEntrypointLegacy() {
  const payload = useRoutePayload<CopilotSweAgentPayload>()
  return <SweAgentPage payload={payload} />
}

export function SweAgentPageEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessSweAgentRoute, 'mainQuery')
  return <SweAgentPage payload={payload} />
}

/**
 * Renders the SweAgent (Copilot coding agent) configuration page for an organization.
 *
 * Displays information about the coding agent capabilities and provides UI controls for:
 * - Repository access selection
 * - Third-party agent configuration (conditionally rendered based on feature flag)
 *
 * The component uses the presence of the `agents` payload prop to determine whether to show
 * per-app agent selections or the old UI.
 *
 * @param props - The component props
 * @param props.payload - The SweAgent route data containing project info, agent configs, and settings
 * @returns A JSX element containing the SweAgent configuration UI
 */
function SweAgentPage({payload: routeData}: {payload: CopilotSweAgentPayload}) {
  return (
    <>
      <PageHeading name={routeData.project_display_name} />
      {routeData.access_warning_banner_content && (
        <Banner variant="warning" title="No Copilot coding agent access" hideTitle className="tmp-mb-3">
          {routeData.access_warning_banner_content}
        </Banner>
      )}
      <div className={styles.topBox}>
        <span>
          With {routeData.project_display_name}, developers can delegate tasks to Copilot, freeing them to focus on the
          creative, complex, and high-impact work that matters most. Simply assign a task to Copilot, wait for the agent
          to request review, then leave feedback on the pull request to iterate.{' '}
          <Link href="https://gh.io/copilot-coding-agent-docs" inline>
            Learn more in the docs.
          </Link>
        </span>
      </div>
      <div className="tmp-mt-4 tmp-mb-4">
        <RepositoryAccessSelection payload={routeData} />
      </div>

      {routeData.agents && routeData.agents.length > 0 && (
        <>
          <Stack gap="condensed">
            <Stack direction="horizontal" align="center">
              <SectionHeading name="Partner agents" />
              <Label variant="success">Preview</Label>
            </Stack>
            <p className="mb-0">
              Enabling an agent allows it to be mentioned in issues and pull requests, and assigned to issues and open
              pull requests. Agents can only be triggered by organization members and repository collaborators, and can
              only be used in this organization&#39;s repositories where the coding agent feature is enabled.
            </p>
          </Stack>

          <div className="tmp-mt-4">
            <ThirdPartyAgentPicker payload={routeData} />
          </div>
        </>
      )}
    </>
  )
}

function RepositoryAccessSelection({payload}: {payload: CopilotSweAgentPayload}) {
  const {
    mode: initialMode,
    selection,
    selections_changed_callback_path,
    mode_changed_callback_path,
    org_login,
    enterprise_name,
    enterprise_slug,
    project_display_name,
    repo_access_enabled,
  } = payload
  const [mode, setMode] = useState<SelectionMode>(initialMode)
  const [selected, setSelected] = useState<PickerRepository[]>(selection)
  const [isPolicyBannerShown, setIsPolicyBannerShown] = useState<boolean>(false)

  const onSelectionChange = async (repos: PickerRepository[]) => {
    // Clear the banner when the user tries to change the selection
    setIsPolicyBannerShown(false)

    // Store the original selection in case the request fails
    const originalSelection = selected

    try {
      setSelected(repos)
      const response = await reactFetchJSON(selections_changed_callback_path, {
        method: 'PUT',
        body: {
          selected_repos: repos.map(repo => repo.id),
        },
      })

      // Check if the response status is ok (2xx)
      if (!response.ok) {
        throw new Error('Failed to update selection')
      }
    } catch {
      // If the request fails, show a banner to inform the user
      setIsPolicyBannerShown(true)

      // Revert to the original selection
      setSelected(originalSelection)
    }
  }

  const onModeChange = async (newMode: string) => {
    // Clear the banner when the user tries to change the mode
    setIsPolicyBannerShown(false)

    // Store the original mode in case the request fails
    const originalMode = mode

    try {
      const selectionMode = newMode as SelectionMode
      setMode(newMode as SelectionMode)
      const response = await reactFetchJSON(mode_changed_callback_path, {
        method: 'PUT',
        body: {
          mode: selectionMode,
        },
      })

      // Check if the response status is ok (2xx)
      if (!response.ok) {
        throw new Error('Failed to update mode')
      }
    } catch {
      // If the request fails, show a banner to inform the user
      setIsPolicyBannerShown(true)

      // Revert to the original mode
      setMode(originalMode)
    }
  }

  const supportedModes = [
    {name: 'no_repos', label: 'No repositories'},
    {...modes.all, name: 'all_repos'},
    modes.buildMultiple({
      selected,
      onSubmit: onSelectionChange,
      scope: {type: 'organization', slug: org_login},
    }),
  ]

  const title = 'Repository access'
  const description = `Choose which repositories ${project_display_name} should be enabled in. To be able to assign an issue to Copilot, the user must have access to ${project_display_name} and it must be enabled for the repository.`
  return (
    <>
      {isPolicyBannerShown && (
        <Banner
          variant="critical"
          title="Failed to save changes"
          hideTitle
          className="tmp-mb-3"
          onDismiss={() => {
            setIsPolicyBannerShown(false)
          }}
        >
          Failed to update selection, please try again later.
        </Banner>
      )}
      <ControlGroup className="borderColor-default px-1">
        {repo_access_enabled ? (
          <ControlGroup.Selector
            selectorIcon={undefined}
            selectedMode={mode}
            onModeChange={onModeChange}
            modes={supportedModes}
            title="Repository access"
            description={`Choose which repositories ${project_display_name} should be enabled in. To be able to assign an issue to Copilot, the user must have access to ${project_display_name} and it must be enabled for the repository.`}
          />
        ) : (
          <ControlGroup.Item>
            <ControlGroup.Title>{title}</ControlGroup.Title>
            <ControlGroup.Description>
              {description}
              {!repo_access_enabled && enterprise_name && enterprise_slug && (
                <div className="mt-2" style={{color: 'var(--fgColor-muted)'}}>
                  <ShieldLockIcon /> Managed by{' '}
                  <Link inline href={`/enterprises/${enterprise_slug}`}>
                    {enterprise_name}
                  </Link>
                </div>
              )}
            </ControlGroup.Description>
            <ControlGroup.Custom>
              <span>
                <ShieldLockIcon /> <span style={{color: 'var(--fgColor-default'}}>Disabled</span>
              </span>
            </ControlGroup.Custom>
          </ControlGroup.Item>
        )}
      </ControlGroup>
    </>
  )
}

function ThirdPartyAgentPicker({payload}: {payload: CopilotSweAgentPayload}) {
  const {agents, third_party_agent_enablement_callback_path} = payload

  return (
    <CopilotSweAgentThirdPartyAgentPicker
      agents={agents === undefined ? [] : agents}
      third_party_agent_enablement_callback_path={
        third_party_agent_enablement_callback_path === undefined ? '' : third_party_agent_enablement_callback_path
      }
    />
  )
}
