import {AlertIcon, XIcon, type Icon} from '@primer/octicons-react'
import {Box, Flash} from '@primer/styled-react'
import {Octicon} from '@primer/react/deprecated'
import type {ComponentProps} from 'react'
import type React from 'react'

type FlashProps = React.PropsWithChildren<
  ComponentProps<typeof Flash> & {
    variant?: 'default' | 'warning' | 'success' | 'danger'
    onClose?: () => void
    icon?: Icon
  }
>

function MessageIcon({variant, icon}: {variant?: FlashProps['variant']; icon?: Icon}) {
  if (variant === 'warning' || variant === 'danger') {
    return <Octicon icon={icon || AlertIcon} />
  }

  if (icon) {
    return <Octicon icon={icon} />
  }

  return null
}

export function CopilotFlash({children, onClose, icon, sx, ...rest}: FlashProps) {
  if (!children) {
    return null
  }

  return (
    <Flash sx={sx} {...rest}>
      <MessageIcon variant={rest.variant} icon={icon} />
      {children}
      {onClose && (
        <Box sx={{cursor: 'pointer'}} onClick={onClose}>
          <XIcon />
        </Box>
      )}
    </Flash>
  )
}
