import {App} from './App'
import {registerNavigatorApp, registerDataRouterApp} from '@github-ui/react-core/register-app'
import {jsonRoute} from '@github-ui/react-core/json-route'
import {copilotForBusinessAppBuilder} from './config/app-builder'
import {copilotForBusinessSeatManagementRoute} from './routes/seat-management-route'
import {copilotForBusinessPoliciesRoute} from './routes/policies-route'
import {copilotForBusinessSweAgentRoute} from './routes/swe-agent-route'
import {copilotForBusinessModelsRoute} from './routes/models-route'
import {
  copilotForBusinessStandaloneSeatManagementRoute,
  copilotForBusinessStandaloneSeatManagementEnterpriseRoute,
} from './routes/standalone-seat-management-route'
import {PoliciesPageEntrypoint, PoliciesPageEntrypointLegacy} from './routes/Policies'
import {SweAgentPageEntrypoint, SweAgentPageEntrypointLegacy} from './routes/SweAgent'
import {ModelsPageEntrypoint, ModelsPageEntrypointLegacy} from './routes/Models'
import {SeatManagementEntrypoint, SeatManagementEntrypointLegacy} from './routes/SeatManagement'
import {
  CopilotStandaloneSeatManagementEnterpriseEntrypoint,
  CopilotStandaloneSeatManagementEntrypoint,
  CopilotStandaloneSeatManagementEntrypointLegacy,
} from './routes/StandaloneSeatManagement'

// Remove once cfb_package_data_router FF is fully shipped
registerNavigatorApp('copilot-for-business', () => ({
  App,
  routes: [
    jsonRoute({
      path: '/organizations/:org/settings/copilot/seat_management',
      Component: SeatManagementEntrypointLegacy,
    }),
    jsonRoute({path: '/organizations/:org/settings/copilot/policies', Component: PoliciesPageEntrypointLegacy}),
    jsonRoute({path: '/organizations/:org/settings/copilot/coding_agent', Component: SweAgentPageEntrypointLegacy}),
    jsonRoute({path: '/organizations/:org/settings/copilot/models', Component: ModelsPageEntrypointLegacy}),
    jsonRoute({
      path: '/enterprises/:slug/licensing/copilot/seat_management',
      Component: CopilotStandaloneSeatManagementEntrypointLegacy,
    }),
    jsonRoute({
      path: '/enterprises/:slug/enterprise_licensing/copilot/seat_management',
      Component: CopilotStandaloneSeatManagementEntrypointLegacy,
    }),
  ],
}))

export const copilotForBusinessApp = copilotForBusinessAppBuilder.createDataRouterAppFromRoutes([
  copilotForBusinessSeatManagementRoute.toRoute({
    Component: SeatManagementEntrypoint,
  }),
  copilotForBusinessPoliciesRoute.toRoute({
    Component: PoliciesPageEntrypoint,
  }),
  copilotForBusinessSweAgentRoute.toRoute({
    Component: SweAgentPageEntrypoint,
  }),
  copilotForBusinessModelsRoute.toRoute({
    Component: ModelsPageEntrypoint,
  }),
  copilotForBusinessStandaloneSeatManagementRoute.toRoute({
    Component: CopilotStandaloneSeatManagementEntrypoint,
  }),
  copilotForBusinessStandaloneSeatManagementEnterpriseRoute.toRoute({
    Component: CopilotStandaloneSeatManagementEnterpriseEntrypoint,
  }),
])
registerDataRouterApp(copilotForBusinessApp)
