import {Link} from '@primer/react'
import {useState, useCallback} from 'react'
import type {
  CopilotForBusinessGeneralPolicy,
  CopilotForBusinessModelsPayload,
  CopilotForBusinessPoliciesPayload,
} from '../types'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import {useOptions} from '../hooks/use-options'
import {MemberRequestsComponent} from './MemberRequestsComponent'
import PolicyActionMenu from './PolicyActionMenu'

export default function GeneralPolicy({
  payload,
  policy,
  className = '',
}: {
  payload: CopilotForBusinessPoliciesPayload | CopilotForBusinessModelsPayload
  policy: CopilotForBusinessGeneralPolicy
  className?: string
}) {
  const {onSelect, options, selected, loading} = useOptions(payload, {
    items: policy.options,
    controls: policy.manages,
  })

  const disabled = !policy.configurable

  const hasMemberRequests =
    policy.manages === 'swe_agent' && 'swe_agent_member_requests' in payload && !!payload.swe_agent_member_requests

  const [showMemberRequests, setShowMemberRequests] = useState(hasMemberRequests)
  const handleSelect = useCallback(
    (item: ActionMenuButtonOption) => {
      const prevValue = selected?.value
      onSelect(item)
      if (hasMemberRequests && item.value !== prevValue) {
        setShowMemberRequests(false)
      }
    },
    [onSelect, selected?.value, hasMemberRequests],
  )

  if (!policy.visible) {
    return null
  }

  return (
    <>
      <div data-testid={`cfb-policies-${policy.manages}-feature`} style={{maxWidth: 750}} className={className}>
        <PreviewFeatureHeading title={policy.displayname} beta={policy.preview} />
        {policy.description}
        <br />
        {policy.helpurl && policy.helptext && (
          <Link href={policy.helpurl} inline>
            {policy.helptext}
          </Link>
        )}
        {hasMemberRequests && showMemberRequests && payload.swe_agent_member_requests && (
          <div style={{marginTop: '16px'}}>
            <MemberRequestsComponent memberRequests={payload.swe_agent_member_requests} entityType="member" />
          </div>
        )}
      </div>
      <PolicyActionMenu
        options={options}
        onSelect={hasMemberRequests ? handleSelect : onSelect}
        disabled={disabled}
        selected={selected}
        loading={loading}
        actionMenuTestId={`cfb-policies-${policy.manages}-control`}
        disabledTestId={`cfb-policies-${policy.manages}-feature-locked`}
      />
    </>
  )
}
