import {ShieldLockIcon} from '@primer/octicons-react'
import {ActionMenuButton} from '../traditional/components/ActionMenuButton'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import {DEFAULT_MENU_OPTION} from '../constants'

type PolicyActionMenuProps = {
  options: ActionMenuButtonOption[]
  onSelect: (item: ActionMenuButtonOption) => void
  disabled: boolean
  inputDisabled?: boolean | undefined
  selected: ActionMenuButtonOption | undefined
  loading: boolean
  actionMenuTestId: string
  disabledTestId: string
}

export default function PolicyActionMenu({
  options,
  onSelect,
  disabled,
  selected,
  loading,
  actionMenuTestId,
  disabledTestId,
  inputDisabled,
}: PolicyActionMenuProps) {
  // if the policy is unconfigured and not configurable, we will show disabled instead of 'Unconfigured'
  const lockedEnablementText = selected?.value === DEFAULT_MENU_OPTION.value ? 'Disabled' : selected?.title
  return (
    <>
      {disabled ? (
        <span data-testid={disabledTestId}>
          <ShieldLockIcon /> {lockedEnablementText ?? 'Disabled'}
        </span>
      ) : (
        <ActionMenuButton
          title={selected?.title ?? 'Disabled'}
          options={options}
          onSelect={onSelect}
          disabled={inputDisabled ?? disabled}
          loading={loading}
          data-testid={actionMenuTestId}
        />
      )}
    </>
  )
}
