import type React from 'react'

import {ActionMenu, Spinner} from '@primer/react'
import {ActionList, Box} from '@primer/styled-react'

export type ActionMenuButtonOption = {
  id: string
  title: React.ReactNode
  value: unknown
  description?: React.ReactNode
  selected?: boolean
  testId?: string
}

export function ActionMenuButton(props: {
  title: React.ReactNode
  options: ActionMenuButtonOption[]
  disabled: boolean
  loading?: boolean
  onSelect(option: ActionMenuButtonOption): void
  'data-testid'?: string
  variant?: 'default' | 'primary' | 'danger' | 'invisible'
}) {
  return (
    <Box
      sx={{display: 'grid', gap: 2, alignItems: 'center', gridTemplateColumns: '1fr auto'}}
      data-testid={props['data-testid']}
    >
      {props.loading && <Spinner size="small" />}
      <ActionMenu>
        <ActionMenu.Button disabled={props.disabled} variant={props.variant || 'default'}>
          {props.title}
        </ActionMenu.Button>

        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="single" showDividers>
            {props.options.map(option => {
              return (
                <ActionList.Item
                  sx={{m: 0}}
                  key={option.id}
                  selected={option.selected}
                  onSelect={() => props.onSelect(option)}
                  data-testid={option.testId}
                >
                  {option.title}
                  {option.description ? (
                    <ActionList.Description variant="block">{option.description}</ActionList.Description>
                  ) : null}
                </ActionList.Item>
              )
            })}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </Box>
  )
}
