// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {useEnsureOrgName} from './use-ensure-org-name'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import type {MenuItem, CopilotForBusinessPoliciesPayload, CopilotForBusinessModelsPayload} from '../types'
import {useCallback, useMemo, useState} from 'react'
import {useCreateMutator} from './use-fetchers'
import {seatManagementEndpoint} from '../traditional/helpers/api-endpoints'
import {DEFAULT_MENU_OPTION} from '../constants'

export function useOptions(
  payload: CopilotForBusinessPoliciesPayload | CopilotForBusinessModelsPayload,
  {
    items,
    controls,
    defaultOption = DEFAULT_MENU_OPTION,
  }: {items: MenuItem[]; controls: string; defaultOption?: ActionMenuButtonOption},
) {
  const org = useEnsureOrgName(payload)
  const {addToast} = useToastContext()

  // options
  const [options, setOptions] = useState<ActionMenuButtonOption[]>(items)

  const normalizedOptions = useMemo(() => {
    return options.map(item => ({
      ...item,
      testId: `cfb-policy-option-${item.title}`,
    }))
  }, [options])

  // derrived selected
  const selected = useMemo(() => {
    return options.find(option => option.selected) ?? defaultOption
  }, [options, defaultOption])

  // mutations
  const useCopilotSettingsMutation = useCreateMutator(seatManagementEndpoint, {org})

  const [updateOption, loading] = useCopilotSettingsMutation<Record<string, string>, {success: boolean}>({
    resource: 'policies',
    method: 'PUT',
  })

  const onSelect = useCallback(
    async (item: ActionMenuButtonOption) => {
      updateOption({
        payload: {
          [controls]: item.value as string,
        },
        onError(e) {
          let message = 'Something went wrong. Please try again later.'
          if (e && typeof e === 'object' && 'message' in e) message = String(e.message)

          // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
          addToast({
            message,
            role: 'alert',
            type: 'error',
          })
        },
        onComplete(data) {
          if (data && data.success) {
            setOptions(prev => {
              return prev.map(option => {
                option.selected = option.id === item.id
                return option
              })
            })
          }
        },
      })
    },
    [controls, updateOption, addToast],
  )

  return {
    loading,
    ///
    selected,
    onSelect,
    ///
    options: normalizedOptions,
    setOptions,
  }
}
