import {Link} from '@primer/react'
import type {CopilotMcpRegistryPolicy} from '../types'
import type {ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import PolicyActionMenu from './PolicyActionMenu'

type McpRegistryAccessProps = {
  options: ActionMenuButtonOption[]
  selected: ActionMenuButtonOption | undefined
  onSelect: (option: ActionMenuButtonOption) => void
  loading: boolean
  policy: CopilotMcpRegistryPolicy
  inputDisabled: boolean
}

export default function McpRegistryAccess({
  options,
  selected,
  onSelect,
  loading,
  policy,
  inputDisabled,
}: McpRegistryAccessProps) {
  const disabled = !policy.configurable

  if (!policy.visible) {
    return null
  }

  return (
    <>
      <div data-testid={`cfb-policies-${policy.manages}-feature`} className="tmp-ml-3" style={{maxWidth: 750}}>
        <PreviewFeatureHeading title={policy.displayname} beta={policy.preview!} />
        {policy.description}
        <br />
        {policy.helpurl && policy.helptext && (
          <Link href={policy.helpurl} inline>
            {policy.helptext}
          </Link>
        )}
      </div>
      <PolicyActionMenu
        options={options}
        onSelect={onSelect}
        disabled={disabled}
        inputDisabled={inputDisabled}
        selected={selected}
        loading={loading}
        actionMenuTestId={`cfb-policies-${policy.manages}-control`}
        disabledTestId={`cfb-policies-${policy.manages}-feature-locked`}
      />
    </>
  )
}
